import{hash as c,shuffle as u}from"../../daily/puzzles.js";import{wordBoards as f}from"./word-board-data.js";export function wordBoard(s){const i=f[c(s)%f.length],t=Array(25).fill("#");for(let o=0;o<3;o++)for(let r=0;r<5;r++)t[o*10+r]=i[o][r];for(let o=0;o<3;o++)for(let r=0;r<5;r++)t[r*5+o*2]=i[o+3][r];return{words:i,solution:t}}export function makeWordGrid(s){const{words:i,solution:t}=wordBoard(s),o=[...t],r=u(t.flatMap((n,e)=>n!=="#"?[e]:[]),s+":tiles");let l=0;while(r.length>1&&l<8){const n=r.shift(),e=r.findIndex((a)=>o[n]!==o[a]);if(e<0)break;const d=r.splice(e,1)[0];[o[n],o[d]]=[o[d],o[n]];l++}return{kind:"wordgrid",size:5,words:i,solution:t,initial:o,maxMoves:15}}